// Define the physical parameters of the pendulum
const GRAVITY = 9.81; // m/s^2
const LENGTH = 100; // meters
const MASS = 0.5; // kilograms

// Define the initial conditions
let ANG_INIT = Math.PI / 6; // initial angle in radians
let VEL_INIT = 0; // initial velocity in m/s

// Define some constants
const FPS = 30; // frames per second
const DT = 1 / FPS; // time step in seconds

// Get the canvas element
const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');

// Initialize the angle and velocity
let angle = ANG_INIT;
let velocity = VEL_INIT;

// Initialize the frame count
let frame = 0;

// Function to update the angle and velocity
function update() {
  // Calculate the acceleration
  const acceleration = -GRAVITY * Math.sin(angle) / LENGTH;
  velocity += acceleration * DT;
  angle += velocity * DT;

  // Ensure the angle doesn't exceed the maximum range
  angle %= 2 * Math.PI;
}

// Function to draw the pendulum
function draw() {
  canvas.width = canvas.offsetWidth;
  canvas.height = canvas.offsetHeight;

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.strokeStyle = 'black';
